B.bfe=new A.f_("count_traffic","\uc720\ub3d9\uc778\uad6c\uc640 \uc2e4\uc81c \uad6c\ub9e4\ub97c \ub530\ub85c \uc13c\ub2e4","\uc0ac\ub78c \ubc18\uc751\uacfc \uc22b\uc790\uac00 \uac19\uc740 \ubc29\ud5a5\uc778\uc9c0 \ud655\uc778\ud55c\ub2e4.","\ub0b4\uac00 \ub4e4\uc740 \ub9d0\uc774\ub791 \uc2e4\uc81c \uc22b\uc790\ub97c \ub530\ub85c \ub193\uc73c\ub2c8\uae4c \ud6e8\uc52c \uc798 \ubcf4\uc778\ub2e4.",0,0,0,2)
B.bfi=new A.f_("split_observation","\uc870\uc0ac \uad6c\uc5ed\uc744 \ub098\ub220 \uac01\uc790 \ud655\uc778\ud55c\ub2e4","\uc9c0\uae08\uc758 \uad00\uacc4 \uac70\ub9ac\ub97c \uc874\uc911\ud558\uba70 \uacb0\uacfc\ub9cc \ud569\uce5c\ub2e4.","\uc751. \ub05d\ub098\uace0 \ud569\uce60 \ub54c\ub9cc \ube60\ub728\ub9b0 \uac70 \ud655\uc778\ud558\uc790.",0,1,0,0)
