B.bfj=new A.f_("align_dates","\uc138 \ub9e4\ubb3c\uc758 \uae30\uc900\uc77c\ubd80\ud130 \ub9de\ucd98\ub2e4","\uc11c\ub85c \ub2e4\ub978 \ub0a0\uc9dc\uc758 \uac00\uaca9\uc744 \uac19\uc740 \uc22b\uc790\ucc98\ub7fc \ubcf4\uc9c0 \uc54a\ub294\ub2e4.","\uc774\uc81c \ube44\uad50\uac00 \ub3fc. \ub0a0\uc9dc \ud558\ub098 \ub54c\ubb38\uc5d0 \uacb0\ub860\uc774 \uaf64 \ub2ec\ub77c\uc84c\uc5b4.",0,0,0,2)
B.bfs=new A.f_("share_assumptions","\uac01\uc790 \uc4f4 \uc804\uc81c\ub97c \ud55c \uc904\uc529 \uacf5\uac1c\ud55c\ub2e4","\uacb0\ub860\ubcf4\ub2e4 \uc0dd\uac01\uc758 \uc911\uac04 \uacfc\uc815\uc744 \ub098\ub208\ub2e4.","\ub124 \uc804\uc81c\ub294 \ub0b4\uac00 \uc548 \ub123\uc5c8\ub358 \uac70\uc57c. \ud45c\uc5d0 \ub530\ub85c \ub0a8\uaca8 \ub458\uac8c.",1,1,1,0)
