B.aOH=new A.h5("2000-09-01","\uae68\uc9c0\ub294 \uc870\uac74 \uac8c\uc2dc\ud310","\ucc44\uc544\uac00 \ub77c\uc6b4\uc9c0 \ubcbd\uc5d0 \uac00\uc124\uacfc \ud568\uaed8 \u201c\uc774 \uac00\uc124\uc774 \ud2c0\ub9ac\ub294 \uc870\uac74\u201d\uc744 \ubd99\uc774\ub294 \uce78\uc744 \ub9cc\ub4e4\uc5c8\ub2e4. \uc624\uc9c0\uc6b0\uac00 \uac00\uc7a5 \ub9ce\uc774 \ubd99\uc600\uace0, \uac00\uc7a5 \ub9ce\uc774 \uc9c0\uc6b4 \uac83\ub3c4 \uadf8\uc600\ub2e4.","\uac00\uc124 \uac8c\uc2dc\ud310",B.pj,4285433528,u.u)
B.aOC=new A.h5("2000-12-29","\uccab \ud574\uac00 \ub2eb\ud614\ub2e4","2000\ub144 \ub9c8\uc9c0\ub9c9 \uac70\ub798\uc77c. \uc5f4 \uba85\uc758 \uc7a5\ubd80 \uccab \uad8c\uc774 \ub2e4 \ucc3c\ub2e4. \uc544\ubb34\ub3c4 \uccab \uc7a5\uc758 50,000\uc6d0\uc744 \uc9c0\uc6b0\uc9c0 \uc54a\uc558\uace0, \uc11c\uc544\ub294 \ub9c8\uc9c0\ub9c9 \uc904 \uc544\ub798\uc5d0 \ub2e4\uc74c \uad8c \ubc88\ud638\ub9cc \uc801\uc5c8\ub2e4.","\uccab \ud574 \ub9c8\uac10",B.e_,4294948941,u.n)
B.aOF=new A.h5("2001-04-16","15\uc0b4, \ub450 \ubc88\uc9f8 \ubd04","\ud504\ub85c\uc81d\ud2b8 \uc7ac\uac00\ub3d9 2\uc8fc\ub144. \ud55c\uaddc\uc9c4\uc740 \uc5ec\uc804\ud788 \uc218\uc775\ub960\ubcf4\ub2e4 \uc911\ub2e8\uad8c\uc744 \uba3c\uc800 \ubcf4\uace0\ubc1b\uc558\ub2e4. \uc5f4 \uba85 \uc911 \ub204\uad6c\ub3c4 \uc544\uc9c1 \ub098\uac00\uc9c0 \uc54a\uc558\ub2e4\ub294 \ubb38\uc7a5\uc774 \ubcf4\uace0\uc11c \uccab \uc904\uc774\uc5c8\ub2e4.","2\uc8fc\ub144",B.e_,4288449223,u.y)
B.aOS=new A.h5("2002-01-04","16\uc0b4, \uc7a5\ubd80\uac00 \ub450 \uad8c\uc774 \ub410\ub2e4","\ub450 \ubc88\uc9f8 \uc7a5\ubd80\uc758 \uccab \uc7a5\uc5d0\ub294 \uc6d0\uae08\uc774 \uc544\ub2c8\ub77c \uc9c0\ub09c \ub450 \ud574\uc758 \ucd5c\ub300 \ub099\ud3ed\uc774 \uc801\ud614\ub2e4. \ud559\uc900\uc774 \uc81c\uc548\ud558\uace0 \ucc44\uc544\uac00 \uacc4\uc0b0\ud588\ub2e4.","16\uc0b4",B.e_,4284317603,u.bm)
B.aOI=new A.h5("2003-01-06","17\uc0b4, \uac01\uc790\uc758 \ubc29\uc2dd\uc774 \uac08\ub838\ub2e4","\uac19\uc740 \uc885\ubaa9\uc744 \uc5f4 \uba85\uc774 \uc11c\ub85c \ub2e4\ub978 \uc774\uc720\ub85c \ubcf4\uae30 \uc2dc\uc791\ud588\ub2e4. \uc544\ub9b0\uc740 \uc21c\uc11c\ub97c, \uc774\uc11c\ub294 \uacb0\uc744, \uc9c0\uc6b0\ub294 \ubc18\ub840\ub97c \ubd24\uace0 \uc544\ubb34\ub3c4 \ub0a8\uc758 \ubc29\uc2dd\uc744 \uace0\uce58\ub77c\uace0 \ud558\uc9c0 \uc54a\uc558\ub2e4.","17\uc0b4",B.hV,4293895260,u.n)
